//go:build amd64 && !purego
// +build amd64,!purego

#include "textflag.h"

#define STACK_LOOKUP_FIRST(IDX, OFF, ACC) \
	MOVBQZX	IDX(SP), AX; \
	SHLQ	$4, AX; \
	MOVOU	OFF(DX)(AX*1), ACC

#define STACK_LOOKUP_XOR(IDX, OFF, ACC, TMP) \
	MOVBQZX	IDX(SP), AX; \
	SHLQ	$4, AX; \
	MOVOU	OFF(DX)(AX*1), TMP; \
	PXOR	TMP, ACC

#define STACK_LOOKUP_BLOCK(ACC, TMP) \
	STACK_LOOKUP_FIRST(0, 0, ACC); \
	STACK_LOOKUP_XOR(1, 4096, ACC, TMP); \
	STACK_LOOKUP_XOR(2, 8192, ACC, TMP); \
	STACK_LOOKUP_XOR(3, 12288, ACC, TMP); \
	STACK_LOOKUP_XOR(4, 16384, ACC, TMP); \
	STACK_LOOKUP_XOR(5, 20480, ACC, TMP); \
	STACK_LOOKUP_XOR(6, 24576, ACC, TMP); \
	STACK_LOOKUP_XOR(7, 28672, ACC, TMP); \
	STACK_LOOKUP_XOR(8, 32768, ACC, TMP); \
	STACK_LOOKUP_XOR(9, 36864, ACC, TMP); \
	STACK_LOOKUP_XOR(10, 40960, ACC, TMP); \
	STACK_LOOKUP_XOR(11, 45056, ACC, TMP); \
	STACK_LOOKUP_XOR(12, 49152, ACC, TMP); \
	STACK_LOOKUP_XOR(13, 53248, ACC, TMP); \
	STACK_LOOKUP_XOR(14, 57344, ACC, TMP); \
	STACK_LOOKUP_XOR(15, 61440, ACC, TMP)

#define STACK_PI_INV(IDX) \
	MOVBQZX	IDX(SP), AX; \
	MOVBLZX	0(DX)(AX*1), BX; \
	PINSRB	$IDX, BX, X2

TEXT ·encryptBlockSSEStack(SB), NOSPLIT, $16-24
	MOVQ	dst+0(FP), R8
	MOVQ	src+8(FP), BX
	MOVOU	(BX), X0
	MOVQ	rkeys+16(FP), SI
	LEAQ	·lsEncLookup(SB), DX
	MOVQ	$9, DI

encStackLoop:
	MOVOU	(SI), X1
	PXOR	X1, X0
	MOVOU	X0, 0(SP)
	STACK_LOOKUP_BLOCK(X2, X3)
	ADDQ	$16, SI
	MOVOU	X2, X0
	SUBQ	$1, DI
	JNZ	encStackLoop

	MOVOU	(SI), X1
	PXOR	X1, X0
	MOVOU	X0, (R8)
	RET

TEXT ·decryptBlockSSEStack(SB), NOSPLIT, $16-24
	MOVQ	dst+0(FP), R8
	MOVQ	src+8(FP), BX
	MOVOU	(BX), X0
	MOVQ	rkeys+16(FP), SI
	ADDQ	$144, SI

	LEAQ	·lInvLookup(SB), DX
	MOVOU	X0, 0(SP)
	STACK_LOOKUP_BLOCK(X2, X3)
	MOVOU	X2, X0

	LEAQ	·slDecLookup(SB), DX
	MOVQ	$8, DI

decStackRound:
	MOVOU	(SI), X1
	PXOR	X1, X0
	MOVOU	X0, 0(SP)
	STACK_LOOKUP_BLOCK(X2, X3)
	SUBQ	$16, SI
	MOVOU	X2, X0
	SUBQ	$1, DI
	JNZ	decStackRound

	MOVOU	(SI), X1
	PXOR	X1, X0
	SUBQ	$16, SI
	MOVOU	X0, 0(SP)
	LEAQ	·piInverseTable(SB), DX
	PXOR	X2, X2
	STACK_PI_INV(0)
	STACK_PI_INV(1)
	STACK_PI_INV(2)
	STACK_PI_INV(3)
	STACK_PI_INV(4)
	STACK_PI_INV(5)
	STACK_PI_INV(6)
	STACK_PI_INV(7)
	STACK_PI_INV(8)
	STACK_PI_INV(9)
	STACK_PI_INV(10)
	STACK_PI_INV(11)
	STACK_PI_INV(12)
	STACK_PI_INV(13)
	STACK_PI_INV(14)
	STACK_PI_INV(15)
	MOVOU	(SI), X1
	PXOR	X1, X2
	MOVOU	X2, (R8)
	RET
